-- #141 프로필 이미지 (ADR-0069 decision 3 #37-6, decision 4 #141; ADR-0079): a member's profile
-- image, uploaded in MY 설정 into the media store of #46 (`media_objects`, the new kind
-- `profile_image`). Generated by `drizzle-kit generate`, then hand-edited where marked: this header,
-- and the order of two statements (the unique target before the foreign key that needs it). The
-- snapshot is as generated.
--
-- - media_objects.kind: `profile_image` joins `post_image`. A profile image is attached from the
--   transaction that stores it (`media_objects_profile_image_attached_check`), so the worker's
--   orphan clean-up, which takes only unattached uploads, never removes one.
-- - profiles.image_id: the profile image, or NULL while there is none (every existing row, so no
--   backfill). UNIQUE: one profile's at most, and the index `GET /media/:mediaId` asks by.
-- - profiles_image_fk: the image is a `profile_image` of the profile's own account — the database
--   holds it, whoever writes — through the generated `image_kind` (NULL without an image: a foreign
--   key with a NULL column is not checked) and the unique `(id, owner_id, kind)` on media_objects.
--   RESTRICT, as every foreign key of #46: an image is removed after its profile let go of it.
--
-- buddha_app keeps the default privileges on both tables (the column is written with UPDATE like
-- the 소개, and an image row is inserted and deleted as a post's upload is); no new table or role,
-- so docker/postgres/init/01-roles.sql is unchanged and the tables docs/RESET.md resets already
-- cover both (it only gained the profile-image wording and the `profile-images/` bucket prefix,
-- ADR-0079 결과 2).
ALTER TABLE "media_objects" DROP CONSTRAINT "media_objects_kind_check";--> statement-breakpoint
ALTER TABLE "profiles" ADD COLUMN "image_id" uuid;--> statement-breakpoint
ALTER TABLE "profiles" ADD COLUMN "image_kind" varchar(16) GENERATED ALWAYS AS (CASE WHEN image_id IS NOT NULL THEN 'profile_image' END) STORED;--> statement-breakpoint
-- Hand-moved: generated after the foreign key below, which needs it first.
ALTER TABLE "media_objects" ADD CONSTRAINT "media_objects_id_owner_id_kind_unique" UNIQUE("id","owner_id","kind");--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_image_fk" FOREIGN KEY ("image_id","user_id","image_kind") REFERENCES "public"."media_objects"("id","owner_id","kind") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_image_id_unique" UNIQUE("image_id");--> statement-breakpoint
ALTER TABLE "media_objects" ADD CONSTRAINT "media_objects_profile_image_attached_check" CHECK ("media_objects"."kind" <> 'profile_image' OR "media_objects"."attached_at" IS NOT NULL);--> statement-breakpoint
ALTER TABLE "media_objects" ADD CONSTRAINT "media_objects_kind_check" CHECK ("media_objects"."kind" IN ('post_image', 'profile_image'));
